// Generated by scripts/gen-pages.py — accept/reject by the RECEIVER only (T26, T32).
import { ChangeDetectionStrategy, Component, computed, inject, input, resource, signal, viewChild } from '@angular/core';
import { RouterLink } from '@angular/router';
import { TranslatePipe } from '@ngx-translate/core';
import { HttpErrorResponse } from '@angular/common/http';
import { HttpClient } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { ButtonModule } from 'primeng/button';
import { ToastService } from '@core/errors/toast.service';
import { PageHeaderComponent } from '@shared/ui/page-header/page-header.component';
import { AsyncPageComponent } from '@shared/ui/async-page/async-page.component';
import { KeyValueListComponent } from '@shared/ui/key-value-list/key-value-list.component';
import { StatusStampComponent } from '@shared/ui/status-stamp/status-stamp.component';
import { ReasonDialogComponent } from '@shared/ui/reason-dialog/reason-dialog.component';
import { ConfirmDialogComponent } from '@shared/ui/confirm-dialog/confirm-dialog.component';
import { MoneyPipe } from '@shared/pipes/money.pipe';
import type { ActionResponse, ItemResponse } from '@shared/models/api.models';

interface TransferDetail {
  id: number; sender: string | null; receiver: string | null; custody_id: number | null;
  amount: string; status: string; notes: string | null; rejection_reason: string | null;
  requested_at: string | null; decided_at: string | null; decided_by: string | null;
  cancelled_at: string | null; cancelled_by: string | null;
  can_decide: boolean; can_cancel: boolean;
  custody?: { id: number; agent: string | null; treasury: string | null; amount: string; remaining: string; frozen: string };
}

@Component({
  selector: 'app-transfer-detail',
  standalone: true,
  imports: [TranslatePipe, RouterLink, ButtonModule, PageHeaderComponent, AsyncPageComponent, KeyValueListComponent, StatusStampComponent, ReasonDialogComponent, ConfirmDialogComponent, MoneyPipe],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <app-page-header [title]="'transfer.detail.title' | translate" [subtitle]="'#' + id()">
      <div actions class="u-flex u-gap-2">
        @if (canDecide()) {
          <p-button [label]="'transfer.detail.accept' | translate" size="small" severity="success" (onClick)="acceptDialog.open()" [loading]="sending()" />
          <p-button [label]="'transfer.detail.reject' | translate" size="small" severity="danger" [outlined]="true" (onClick)="rejectDialog.open()" />
        }
        @if (canCancel()) {
          <p-button [label]="'transfers.cancel' | translate" size="small" severity="danger" [outlined]="true" (onClick)="cancelDialog.open()" />
        }
        <p-button [label]="'common.back_to_list' | translate" size="small" severity="secondary" [outlined]="true" routerLink="/transfers" />
      </div>
    </app-page-header>

    <app-async-page [resource]="data" variant="detail" [backLink]="['/transfers']">
      @if (data.value(); as t) {
        <div class="u-mb-4"><app-status-stamp [status]="t.status" namespace="transfer_status" [large]="true" /></div>
        @if (!t.can_decide && t.status === 'pending') {
          <p class="field__hint u-mb-4">{{ 'transfer.detail.only_receiver_hint' | translate }}</p>
        }

        <app-key-value-list [items]="keyValues(t)" />

        @if (t.custody; as c) {
          <section class="chart-card u-mt-4">
            <div class="chart-card__head"><span class="chart-card__title">{{ 'custody.detail.title' | translate }}</span></div>
            <app-key-value-list [items]="[
              { label: 'glossary.agent', value: c.agent ?? '—' },
              { label: 'glossary.treasury', value: c.treasury ?? '—' },
              { label: 'common.amount', value: c.amount | money },
              { label: 'transfer.create.available', value: c.remaining | money },
              { label: 'dashboard.agent.frozen', value: c.frozen | money }
            ]" />
          </section>
        }
      }
    </app-async-page>

    <!-- reject needs a typed reason (T4-01) — the same flow as custodies list -->
    <app-reason-dialog
      #rejectDialog
      [header]="'transfer.detail.confirm_reject' | translate"
      [label]="'transfer.detail.reject_reason' | translate"
      [submitLabel]="'transfer.detail.confirm_reject' | translate"
      [sending]="sending()"
      [error]="actionError()"
      (submit)="submitReject($event)"
    />

    <!-- accept takes no input — a plain confirm (T4-01) -->
    <app-confirm-dialog
      #acceptDialog
      [header]="'transfer.detail.accept' | translate"
      [message]="'transfer.detail.accept_confirm'"
      [confirmLabel]="'transfer.detail.accept' | translate"
      confirmKind="accept"
      (confirmed)="accept()"
    />

    <!-- T6-80: the sender (or a manager) cancels a pending transfer -->
    <app-confirm-dialog
      #cancelDialog
      [header]="'transfers.cancel' | translate"
      [message]="'transfers.cancel_confirm'"
      [confirmLabel]="'transfers.cancel' | translate"
      confirmKind="cancel"
      (confirmed)="cancelTransfer()"
    />
  `,
})
export class TransferDetailPage {
  private http = inject(HttpClient);
  private toast = inject(ToastService);

  id = input.required<number>();
  sending = signal(false);
  actionError = signal<HttpErrorResponse | null>(null);

  private rejectDialogRef = viewChild<ReasonDialogComponent>('rejectDialog');

  data = resource<TransferDetail, { id: number }>({
    params: () => ({ id: this.id() }),
    loader: ({ params }) =>
      firstValueFrom(this.http.get<ItemResponse<TransferDetail>>(`/custody-transfers/${params.id}`)).then((res) => res.data),
  });

  /** data.value() throws on an errored resource (e.g. 404) — null keeps the header alive */
  readonly safeValue = computed(() => {
    try {
      return this.data.value() ?? null;
    } catch {
      return null;
    }
  });

  /** the accept/reject header actions belong to the receiver only */
  readonly canDecide = computed(() => this.safeValue()?.can_decide === true);

  /** T6-80: the sender or a manager may cancel while pending */
  readonly canCancel = computed(() => this.safeValue()?.can_cancel === true);

  /** T6-80: cancel this pending transfer (sender/manager only) */
  cancelTransfer(): void {
    this.sending.set(true);
    this.actionError.set(null);
    void firstValueFrom(this.http.post<ActionResponse>(`/custody-transfers/${this.id()}/cancel`, {}))
      .then((res) => {
        this.sending.set(false);
        this.toast.success(res.message);
        this.data.reload();
      })
      .catch((err: HttpErrorResponse) => {
        this.sending.set(false);
        this.actionError.set(err);
        this.toast.apiError(err.error?.message ?? 'errors.generic', err.error?.code);
      });
  }

  keyValues(t: TransferDetail): { label: string; value: string }[] {
    return [
      { label: 'glossary.sender', value: t.sender ?? '—' },
      { label: 'glossary.receiver', value: t.receiver ?? '—' },
      { label: 'common.amount', value: t.amount },
      { label: 'transfer.list.col_custody', value: t.custody_id ? '#' + t.custody_id : '—' },
      { label: 'common.notes', value: t.notes ?? '—' },
      { label: 'transfer.list.col_requested_at', value: t.requested_at ?? '—' },
      { label: 'transfer.list.col_decided_at', value: t.decided_at ?? '—' },
      { label: 'transfer.list.col_decided_by', value: t.decided_by ?? '—' },
      { label: 'transfer.list.col_rejection', value: t.rejection_reason ?? '—' },
      { label: 'transfers.cancelled_by', value: t.cancelled_by ?? '—' },
    ];
  }

  /** POST approve — keeps the custody_id payload the API expects (T26/T32) */
  accept(): void {
    this.sending.set(true);
    void firstValueFrom(
      this.http.post<ActionResponse>(`/custody-transfers/${this.id()}/approve`, {
        custody_id: this.safeValue()?.custody_id,
      }),
    ).then((res) => {
      this.sending.set(false);
      this.toast.success(res.message);
      this.data.reload();
    }).catch((err: unknown) => {
      this.sending.set(false);
      this.toast.apiError((err as HttpErrorResponse).error?.message ?? '', (err as HttpErrorResponse).error?.code);
    });
  }

  /** POST reject with the typed reason (custodies-list flow: dialog → toast → reload) */
  submitReject(reason: string): void {
    this.sending.set(true);
    this.actionError.set(null);
    void firstValueFrom(
      this.http.post<ActionResponse>(`/custody-transfers/${this.id()}/reject`, { reason }),
    ).then((res) => {
      this.sending.set(false);
      this.rejectDialogRef()?.done();
      this.toast.success(res.message);
      this.data.reload();
    }).catch((err: unknown) => {
      this.sending.set(false);
      const response = err instanceof HttpErrorResponse ? err : null;
      this.actionError.set(response);
      if (response) {
        this.toast.apiError(response.error?.message ?? 'errors.generic', response.error?.code);
      }
    });
  }
}
